def layout_rules(source_path: str | None = None):
    combined = dict(LAYOUT_NAMESPACE_PREFIXES)
    combined.update(dict(LAYOUT_MODULE_PREFIX_REWRITES.get(source_path, [])))
    return sorted(combined.items(), key=lambda pair: (-len(pair[0]), pair[0]))


def layout_namespace(name: str, source_path: str | None = None) -> str:
    for old, new in layout_rules(source_path):
        if name == old or name.startswith(old + "."):
            return new + name[len(old):]
    return name


def initial_target_module(module: str) -> str:
    target = EXACT.get(module, module)
    if module not in EXACT:
        for old, new in PREFIXES:
            if module.startswith(old):
                target = new + module[len(old):]
                break
    return target


def target_module(module: str) -> str:
    target = initial_target_module(module)
    return LAYOUT_MODULE_REWRITES.get(target, target)


def module_path(module: str) -> Path:
    return Path(module.replace(".", "/") + ".lean")


def source_path(module: str, *, source_root: Path) -> Path:
    """Resolve an explicit Lean-source directory containing Quillen/ or R5Lab/."""
    if not re.fullmatch(r"(?:Quillen|R5Lab)(?:\.[^\W\d]\w*)+", module):
        raise ValueError("Expected an original Quillen or R5Lab module identity")
    root = Path(source_root).resolve()
    path = root / module_path(module)
    if not path.resolve().is_relative_to(root):
        raise ValueError("Selected source path escapes its explicit source root")
    return path


def read_source(module: str, *, source_root: Path, expected_revision: str,
                expected_sha256: str) -> tuple[str, dict]:
    """Read a caller-selected source only after exact revision and byte-hash guards.

    source_root is the directory containing the original module tree; its
    enclosing Git checkout supplies the revision. No destination is written.
    """
    if not re.fullmatch(r"[0-9a-f]{40}", expected_revision):
        raise ValueError("An exact Git revision is required")
    if not re.fullmatch(r"[0-9a-f]{64}", expected_sha256):
        raise ValueError("An exact source SHA-256 is required")
    path = source_path(module, source_root=source_root)
    result = subprocess.run(['git', '-C', str(Path(source_root).resolve()),
                             'rev-parse', 'HEAD'], capture_output=True, text=True, check=True)
    actual_revision = result.stdout.strip()
    if actual_revision != expected_revision:
        raise ValueError("Selected source revision does not match expected_revision")
    original = path.read_bytes()
    actual_sha256 = hashlib.sha256(original).hexdigest()
    if actual_sha256 != expected_sha256:
        raise ValueError("Selected source bytes do not match expected_sha256")
    return original.decode('utf-8'), {
        "source_module": module,
        "source_repository": "quillen-k-theory" if module.startswith("Quillen.") else "r5-lab",
        "source_revision": actual_revision,
        "source_sha256": actual_sha256,
    }



def canonicalize(source: str, *, source_path: str | None = None) -> str:
    """Adapt original namespaces, then apply the selected layout map once.

    Imports are already routed by target_module and excluded from both namespace
    passes. Comments and strings retain their original source identity.
    """
    from lean_ci.project import source as lexer
    original_rules = json.loads((ROOT / "docs/namespace-map.json").read_text())["prefix_rewrites"]
    for rules in [original_rules, layout_rules(source_path)]:
        if not rules:
            continue
        clean = lexer.strip_comments_and_strings(source)
        protected = []
        for start in lexer.IMPORT_START.finditer(clean):
            position = start.end()
            modifier = re.match(r"\s+all\b", clean[position:])
            if modifier:
                position += modifier.end()
            while position < len(clean):
                while position < len(clean) and clean[position].isspace():
                    position += 1
                token = lexer.MODULE.match(clean, position)
                if not token or token.group() in lexer.KEYWORDS:
                    break
                protected.append((token.start(), token.end()))
                position = token.end()
        names = dict(rules)
        pattern = re.compile(r"(?<![\w.])(" + "|".join(
            re.escape(old) for old, _ in sorted(rules, key=lambda pair: -len(pair[0])))
            + r")(?=\.|\b)")
        matches = [match for match in pattern.finditer(clean)
                   if not any(a <= match.start() < b for a, b in protected)]
        for match in reversed(matches):
            source = source[:match.start()] + names[match[1]] + source[match.end():]
    return source


def modernize(source: str, *, source_path: str | None = None) -> str:
    source = re.sub(
        r"^(?P<modifier>(?:(?:public|private|meta)\s+)*)import (?P<all>all\s+)?(?P<name>[\w.]+)\s*$",
        lambda m: f"{m['modifier']}import {m['all'] or ''}{target_module(m['name'])}",
        source, flags=re.MULTILINE,
    )
    if not re.search(r"^module\s*$", source, flags=re.MULTILINE):
        source = re.sub(r"^import ", "public import ", source, flags=re.MULTILINE)
        imports = list(re.finditer(r"^(?:(?:public|private|meta)\s+)*import .*$", source,
                                  flags=re.MULTILINE))
        position = imports[-1].end() if imports else 0
        documentation = source.find("/-!", position)
        if documentation >= 0:
            position = source.find("-/", documentation) + 2
        source = source[:position] + "\n\n@[expose] public section\n" + source[position:]
        source = "module\n\n" + source
    source = canonicalize(source, source_path=source_path)
    if not source.lstrip().startswith("/-\nCopyright"):
        source = ("/-\nCopyright (c) 2026 Aglib contributors. All rights reserved.\n"
                  "Released under Apache 2.0 license as described in the file LICENSE.\n"
                  "Authors: R5Lab contributors\n-/\n" + source)
    return source


def write_source(module: str, *, source: str | None = None,
                 destination: str | None = None) -> dict:
    """Retired compatibility entry point; redesigned module writes are forbidden."""
    raise RuntimeError("Initial extraction writing is retired; use the current assigned author pipeline")


def record(group: str, entries: list[dict]) -> None:
    """Retired compatibility entry point; immutable provenance is never rewritten."""
    raise RuntimeError("Initial extraction recording is retired; provenance writes require their owner")
